const state={temperature:5,appliedMilliTesla:30},chart=document.getElementById('chart'),NS='http://www.w3.org/2000/svg';function el(tag,attrs,text){const e=document.createElementNS(NS,tag);for(const[k,v]of Object.entries(attrs))e.setAttribute(k,v);if(text!==undefined)e.textContent=text;chart.append(e);return e;}function draw(){const m=CondensedCore.build(state),X=t=>70+660*t/10,Y=q=>370-300*q;chart.replaceChildren();for(let i=0;i<=5;i++){el('text',{x:X(i*2),y:395,'text-anchor':'middle'},i*2);el('line',{x1:70,x2:730,y1:Y(i/5),y2:Y(i/5),stroke:'#34435b'});el('text',{x:60,y:Y(i/5)+5,'text-anchor':'end'},(i/5).toFixed(1));}el('text',{x:400,y:425,'text-anchor':'middle'},'Temperature (K)');el('text',{x:15,y:210,transform:'rotate(-90 15 210)','text-anchor':'middle'},'Phenomenological order index');for(const branch of m.branches){const color=branch.kind==='normal'?'#60b5ff':'#f4c35b';el('polyline',{points:branch.points.map(p=>X(p[0])+','+Y(p[1])).join(' '),fill:'none',stroke:color,'stroke-width':3,'data-branch':branch.kind});const point=branch.endOpen?branch.points.at(-1):branch.startOpen?branch.points[0]:null;if(point)el('circle',{cx:X(point[0]),cy:Y(point[1]),r:5,fill:'#101827',stroke:color,'stroke-width':2,'data-open-end':branch.kind});}if(m.transitionTemperatureK!==null)el('line',{x1:X(m.transitionTemperatureK),x2:X(m.transitionTemperatureK),y1:55,y2:370,stroke:'#b5a6c8','stroke-dasharray':'4 5','data-boundary':m.transitionTemperatureK});if(m.orderParameterIndex!==null)el('circle',{cx:X(m.temperature),cy:Y(m.orderParameterIndex),r:4,fill:'white','data-selected':'true'});document.getElementById('readout').textContent=`At ${m.temperature.toPrecision(6)} K and μ₀Ha = ${m.appliedMilliTesla} mT: ${m.boundary&&m.appliedMilliTesla>0?'coexistence boundary; no unique homogeneous order index':m.superconducting?'superconducting branch':'normal state'}. ${m.gibbsDifferenceJPerM3===null?'Superconducting Gibbs branch unavailable at or above Tc.':'Δg = '+m.gibbsDifferenceJPerM3.toPrecision(6)+' J/m³.'}`;document.getElementById('boundary').disabled=m.transitionTemperatureK===null;window.CondensedReview=m;}for(const[id,key,max]of [['temperature','temperature',10],['field','appliedMilliTesla',100]])document.getElementById(id).onchange=e=>{const v=e.target.valueAsNumber;if(!Number.isFinite(v)||v<0||v>max){e.target.value=state[key];return;}state[key]=v;draw();};document.getElementById('boundary').onclick=()=>{const t=CondensedCore.build(state).transitionTemperatureK;if(t!==null){state.temperature=t;document.getElementById('temperature').value=t;draw();const viewport=document.querySelector('.plot'),scale=chart.getBoundingClientRect().width/800;viewport.scrollLeft=Math.max(0,(70+660*t/10)*scale-viewport.clientWidth/2);}};document.getElementById('reset').onclick=()=>{Object.assign(state,{temperature:5,appliedMilliTesla:30});document.getElementById('temperature').value=5;document.getElementById('field').value=30;draw();};draw();